const names=['v8','turbofan','rotary','radial','steam','stirling','electric','rocket'];const accents={v8:'#e32245',turbofan:'#2656df',rotary:'#ba3e45',radial:'#a56b2c',steam:'#9a662d',stirling:'#ad4f3b',electric:'#6552bc',rocket:'#267895'};const $=id=>document.getElementById(id);let active=null;const loaded=new Set(),resume=new Map(),observers=new Map();
function sizeFrame(name){const f=$('frame-'+name);if(!loaded.has(name)||name!==active)return;const main=f.contentDocument?.querySelector('main');if(main)f.style.height=Math.ceil(main.getBoundingClientRect().height+4)+'px';}
function visibility(name,visible){if(!loaded.has(name))return;const f=$('frame-'+name),w=f.contentWindow,play=f.contentDocument.getElementById('play');w.__studyHidden=!visible;if(!visible){resume.set(name,!!play?.textContent.includes('Pause'));if(resume.get(name))play.click();}else if(resume.get(name)){if(play?.textContent.includes('Play'))play.click();resume.set(name,false);}if(visible)sizeFrame(name);}
for(const name of names){const f=$('frame-'+name);f.addEventListener('load',()=>{if(!f.contentDocument?.querySelector('main'))return;loaded.add(name);const observer=new ResizeObserver(()=>sizeFrame(name));observer.observe(f.contentDocument.querySelector('main'));observers.set(name,observer);visibility(name,active===name);sizeFrame(name);f.contentDocument.fonts?.ready.then(()=>sizeFrame(name));});}
function choose(name,writeHash=true){if(!names.includes(name))throw Error('Unknown engine study');if(active===name)return;if(active)visibility(active,false);active=name;for(const key of names){const selected=key===name;$('panel-'+key).hidden=!selected;$('tab-'+key).setAttribute('aria-selected',String(selected));$('tab-'+key).tabIndex=selected?0:-1;}document.documentElement.style.setProperty('--accent',accents[name]);const f=$('frame-'+name);if(!f.getAttribute('src'))f.src=f.dataset.src;else visibility(name,true);if(writeHash){history.replaceState(null,'','#'+name);window.scrollTo?.({top:0,behavior:'auto'});}sizeFrame(name);}
for(const name of names)$('tab-'+name).onclick=()=>choose(name);
document.querySelector('.lab-tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const target=e.key==='Home'?names[0]:e.key==='End'?names.at(-1):names[(names.indexOf(active)+(e.key==='ArrowLeft'?names.length-1:1))%names.length];choose(target);$('tab-'+target).focus();});
$('reset-study').onclick=()=>{if(!loaded.has(active))return;$('frame-'+active).contentDocument.getElementById('reset')?.click();};window.addEventListener('hashchange',()=>choose(names.includes(location.hash.slice(1))?location.hash.slice(1):'v8',false));window.addEventListener('resize',()=>sizeFrame(active));choose(names.includes(location.hash.slice(1))?location.hash.slice(1):'v8',false);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'select_engine_study',description:'Switch among the eight engine studies on this page.',inputSchema:{type:'object',properties:{engine:{type:'string',enum:names}},required:['engine'],additionalProperties:false},execute(input){if(!input||Object.keys(input).length!==1||!names.includes(input.engine))throw Error('Choose an available engine study');choose(input.engine);return {engine:active};}})).catch(()=>{});}catch{}}
